<template>
  <main v-if="!doctor" class="login-shell">
    <section class="login-card">
      <div class="brand-mark">✚</div><p class="eyebrow">NEUSOFT HEALTH</p><h1>体检报告管理</h1>
      <p class="sub">医生工作台 · 登录后管理预约与报告</p>
      <form @submit.prevent="login" class="login-form">
        <label>医生编号<input v-model.trim="credentials.docCode" required placeholder="请输入医生编号" autocomplete="username"></label>
        <label>登录密码<input v-model="credentials.password" required type="password" placeholder="请输入密码" autocomplete="current-password"></label>
        <el-button class="primary" type="primary" native-type="submit" :disabled="busy">{{ busy ? '登录中…' : '登录工作台' }}</el-button>
      </form>
      <p v-if="error" class="error" role="alert">{{ error }}</p>
      
    </section>
  </main>
  <div v-else class="app-shell">
    <aside class="sidebar"><div class="side-brand"><span class="side-icon">✚</span><div><strong>东软体检</strong><small>报告管理工作台</small></div></div><p class="nav-label">工作空间</p><button class="nav-item" :class="{active:!['consultations','doctorQueue'].includes(route.name)}" @click="back">▦ <span>预约与报告</span></button><button class="nav-item consult-nav" :class="{active:route.name==='consultations'}" @click="router.push('/consultations')">✉ <span>在线咨询</span></button><button class="nav-item consult-nav" :class="{active:route.name==='doctorQueue'}" @click="router.push('/doctorQueue')">☷ <span>医生预约排队</span></button><div class="side-bottom"><span class="avatar">医</span><div><strong>{{ doctor.realName }}</strong><small>{{ doctor.docCode }}</small></div><button class="logout" @click="logout">退出</button></div></aside>
    <div class="workspace"><header class="topbar"><div><span class="crumb">医生工作台</span><span class="slash"> / </span><strong>{{ route.name==='doctorQueue' ? '医生预约排队' : route.name==='consultations' ? '在线咨询' : selected ? '报告详情' : '预约管理' }}</strong></div><span class="top-tag">体检报告管理</span></header>
      <section class="content">
        <DoctorQueue v-if="route.name==='doctorQueue'"/><ConsultationDesk v-else-if="route.name==='consultations'"/><div v-else-if="!selected">
          <div class="page-head"><div><p class="eyebrow">APPOINTMENTS</p><h2>预约管理</h2><p class="sub">查询体检预约，录入检查结果并归档报告。</p></div><button class="secondary" @click="loadOrders">↻ 刷新</button></div>
          <div class="metrics"><div class="metric"><span>当前筛选结果</span><strong>{{ total }}</strong><small>条预约记录</small></div><div class="metric"><span>当前页</span><strong>{{ orders.length }}</strong><small>条记录</small></div><div class="metric note"><span>工作提示</span><strong>报告录入</strong><small>请选择预约后创建或编辑报告</small></div></div>
          <div class="panel"><div class="panel-title"><div><h3>预约列表</h3><p>按预约手机号、体检人姓名、性别、日期、套餐或状态筛选</p></div></div>
            <form class="filters" @submit.prevent="search"><input v-model.trim="filter.userId" aria-label="手机号" placeholder="输入 11 位手机号"><input v-model.trim="filter.realName" aria-label="体检人姓名" maxlength="20" placeholder="输入体检人姓名"><select v-model="filter.sex" aria-label="性别"><option value="">全部性别</option><option value="1">男</option><option value="0">女</option></select><input v-model="filter.orderDate" aria-label="体检日期" type="date"><select v-model="filter.state" aria-label="归档状态"><option value="">全部状态</option><option value="1">未归档</option><option value="2">已归档</option></select><select v-model="filter.smId" aria-label="套餐"><option value="">全部套餐</option><option v-for="m in meals" :key="m.smId" :value="String(m.smId)">{{ m.name }}</option></select><el-button class="primary" type="primary" native-type="submit">查询</el-button><button type="button" class="text-button" @click="resetFilters">重置</button></form>
            <div class="table-wrap"><table><thead><tr><th>预约编号</th><th>体检人</th><th>性别</th><th>体检套餐</th><th>预约日期</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="o in orders" :key="o.orderId"><td class="id">#{{ o.orderId }}</td><td><strong>{{ o.realName }}</strong><small>{{ o.patientType===2 ? '家属 · 预约人：'+o.bookingName+' / ' : '' }}{{ o.userId }}</small></td><td>{{ o.sex===1 ? '男' : o.sex===0 ? '女' : '—' }}</td><td>{{ o.setmealName }}<small>{{ o.hospitalName }}</small></td><td>{{ o.orderDate }}</td><td><span class="badge" :class="o.state===1?'pending':'done'">{{ o.state===1?'未归档':'已归档' }}</span></td><td><button class="link" @click="openOrder(o)">查看报告 →</button></td></tr></tbody></table><div v-if="orders.length===0" class="empty">暂无预约记录</div></div>
            <div class="pagination"><span>共 {{ total }} 条</span><div><button class="secondary" :disabled="pageNum<=1" @click="pageNum--;loadOrders()">上一页</button><span class="page-no">{{ pageNum }}</span><button class="secondary" :disabled="pageNum*pageSize>=total" @click="pageNum++;loadOrders()">下一页</button></div></div>
          </div>
        </div>
        <div v-else><button class="back" @click="back">← 返回预约列表</button><div class="page-head detail-head"><div><p class="eyebrow">EXAMINATION REPORT</p><h2>体检报告 <span class="order-number">#{{ selected.orderId }}</span></h2><p class="sub">{{ selected.realName }}{{selected.patientType===2 ? '（家属）' : '（本人）'}} · 预约账号 {{ selected.userId }} · {{ selected.setmealName }} · {{ selected.orderDate }}</p></div><span class="badge" :class="selected.state===1?'pending':'done'">{{ selected.state===1?'未归档':'已归档' }}</span></div>
          <section class="panel patient-panel"><div class="patient-head"><img src="/img/user.png" alt="" class="patient-avatar"><div><h3>体检人信息</h3><p>预约编号 #{{selected.orderId}} · {{selected.patientType===2?'家属预约':'本人预约'}}</p></div></div><div class="patient-grid"><div><span>姓名</span><strong>{{selected.realName}}</strong></div><div><span>性别</span><strong>{{selected.sex===1?'男':selected.sex===0?'女':'—'}}</strong></div><div><span>出生日期</span><strong>{{selected.patientBirthday || '—'}}</strong></div><div><span>证件号码</span><strong>{{maskId(selected.patientIdentityCard)}}</strong></div><div><span>预约账号</span><strong>{{selected.userId}}</strong></div><div><span>体检机构</span><strong>{{selected.hospitalName}}</strong></div></div></section>
          <div class="detail-grid"><section class="panel detail-panel"><div class="panel-title"><div><h3>检查项目</h3><p>录入各项检查结果并标记异常</p></div><button v-if="!reports.length && selected.state===1" class="primary" @click="createTemplate">创建报告模板</button></div><div v-if="!reports.length" class="empty">尚未创建报告模板</div><div v-for="r in reports" :key="r.cirId" class="exam-group"><div class="exam-head"><strong>{{ r.ciName }}</strong><button v-if="selected.state===1 && r.details.length" class="link" @click="saveDetails(r)">保存本项</button></div><div v-if="!r.details.length" class="muted">暂无检查明细</div><div v-for="d in r.details" :key="d.cidrId" class="exam-row"><label>{{ d.name }} <small>{{ d.unit || '' }} {{ d.normalValueString || '' }}</small><input v-model="d.value" :disabled="selected.state===2" placeholder="输入检查结果"></label><label class="check"><input type="checkbox" :checked="d.isError===1" :disabled="selected.state===2" @change="d.isError=$event.target.checked ? 1 : 0"> 异常</label></div></div></section>
            <section class="panel detail-panel"><div class="panel-title"><div><h3>总检结论</h3><p>为本次体检添加总结和建议</p></div></div><div v-for="item in conclusions" :key="item.orId" class="conclusion"><strong>{{ item.title }}</strong><p>{{ item.content || '—' }}</p><div v-if="selected.state===1"><button class="link" @click="editConclusion(item)">编辑</button><button class="link danger" @click="removeConclusion(item)">删除</button></div></div><div v-if="!conclusions.length" class="muted space">暂无总检结论</div><form v-if="selected.state===1" class="conclusion-form" @submit.prevent="saveConclusion"><label>结论标题<input v-model.trim="draft.title" maxlength="40" required placeholder="请输入标题"></label><label>结论内容<textarea v-model="draft.content" maxlength="400" rows="4" placeholder="填写结论与建议"></textarea></label><div class="actions"><button class="primary">{{ draft.orId ? '保存修改' : '添加结论' }}</button><button v-if="draft.orId" type="button" class="text-button" @click="clearDraft">取消编辑</button></div></form><div class="archive"><p>请填写并保存全部检查结果，至少添加一条总检结论后归档。</p><button class="secondary" :disabled="!archiveReady" @click="archiveOrder">归档报告</button></div></section></div>
        </div>
        <div v-if="notice" class="toast" role="status">{{ notice }}</div><div v-if="error" class="error floating" role="alert">{{ error }} <button class="link" @click="error=''">关闭</button></div>
      </section>
    </div>
  </div>
</template>
<script setup>
import { ref, reactive, computed, onMounted, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElMessageBox } from 'element-plus'
import axios from 'axios'
import ConsultationDesk from './components/ConsultationDesk.vue'
import DoctorQueue from './components/DoctorQueue.vue'
const router=useRouter(), route=useRoute(), initialized=ref(false)
const doctor=ref(null), credentials=reactive({docCode:'',password:''}), busy=ref(false), error=ref(''), notice=ref('')
const filter=reactive({userId:'',realName:'',sex:'',orderDate:'',state:'',smId:''}), pageNum=ref(1), pageSize=10, total=ref(0), orders=ref([]), meals=ref([]), selected=ref(null), reports=ref([]), conclusions=ref([]), savedDetails=ref({}), draft=reactive({orId:null,title:'',content:''})
const signature=r=>JSON.stringify(r.details.map(d=>({id:d.cidrId,value:d.value,isError:d.isError})))
const archiveReady=computed(()=>{
  const details=reports.value.flatMap(r=>r.details)
  return selected.value?.state===1 && reports.value.length>0 && details.length>0 &&
    details.every(d=>typeof d.value==='string' && d.value.trim().length>0) &&
    reports.value.every(r=>savedDetails.value[r.cirId]===signature(r)) &&
    conclusions.value.length>0 && !draft.orId && !draft.title.trim() && !draft.content.trim()
})
const api=axios.create({baseURL:'/tijiancms',timeout:10000})
api.interceptors.response.use(response=>response, err=>{ if(err.response?.status===401){ sessionStorage.removeItem('tijianDoctor');doctor.value=null;selected.value=null;initialized.value=false;router.replace('/login') } return Promise.reject(err) })
async function call(path,data) { const res=await api.post(path,data); return res.data }
function maskId(value){return value && value.length>=8 ? value.slice(0,4)+'**********'+value.slice(-4) : '—'}
function fail(e) { error.value=e.response?.data?.message || '操作未完成，请检查输入与后端服务。'; notice.value='' }
function success(s) { error.value='';notice.value=s;setTimeout(()=>{notice.value=''},3000) }
async function login() { busy.value=true;error.value='';try { const d=await call('/doctor/getDoctorByCodeByPass',credentials); if(!d){error.value='医生编号或密码错误';return} doctor.value=d;sessionStorage.setItem('tijianDoctor',JSON.stringify(d));credentials.password='';await router.replace('/ordersList');await init();initialized.value=true;await syncRoute() } catch(e){fail(e)} finally {busy.value=false} }
async function logout(){try{await call('/auth/logout',{})}catch(e){if(e.response?.status!==401){fail(e);return}}sessionStorage.removeItem('tijianDoctor');doctor.value=null;selected.value=null;initialized.value=false;credentials.password='';error.value='';await router.replace('/login')}
async function init(){try{meals.value=await call('/setmeal/listSetmeal')}catch(e){fail(e)}}
async function loadOrders(){try{error.value='';const body={pageNum:pageNum.value,pageSize};if(filter.userId)body.userId=filter.userId;if(filter.realName)body.realName=filter.realName;if(filter.sex!=='')body.sex=Number(filter.sex);if(filter.orderDate)body.orderDate=filter.orderDate;if(filter.state)body.state=Number(filter.state);if(filter.smId)body.smId=Number(filter.smId);const result=await call('/orders/listOrders',body);orders.value=result.records;total.value=result.total}catch(e){fail(e)}}
function search(){pageNum.value=1;loadOrders()} function resetFilters(){filter.userId='';filter.realName='';filter.sex='';filter.orderDate='';filter.state='';filter.smId='';search()}
async function syncRoute(){
  if(!doctor.value || !initialized.value) return
  if(route.name==='ordersContent'){
    const id=Number(route.query.orderId)
    if(!Number.isInteger(id) || id<=0){await router.replace('/ordersList');return}
    try{const order=await call('/orders/getOrdersById',{orderId:id});if(!order){error.value='预约不存在';await router.replace('/ordersList');return}selected.value=order;clearDraft();await loadReport()}catch(e){fail(e)}
  }else{selected.value=null;reports.value=[];conclusions.value=[];if(route.name==='ordersList')await loadOrders()}
}
watch(()=>route.fullPath,()=>{syncRoute()})
async function openOrder(o){await router.push({name:'ordersContent',query:{orderId:o.orderId}})}
function back(){if(route.name==='ordersList'){selected.value=null;loadOrders()}else router.push('/ordersList')}
async function loadReport(){try{const id={orderId:selected.value.orderId};[reports.value,conclusions.value]=await Promise.all([call('/ciReport/listCiReport',id),call('/overallResult/listOverallResultByOrderId',id)]);savedDetails.value=Object.fromEntries(reports.value.map(r=>[r.cirId,signature(r)]))}catch(e){fail(e)}}
async function createTemplate(){try{await call('/ciReport/createReportTemplate',{orderId:selected.value.orderId});await loadReport();success('报告模板已创建')}catch(e){fail(e)}}
async function saveDetails(r){try{const payload=r.details.map(d=>({...d}));await call('/ciDetailedReport/updateCiDetailedReport',payload);savedDetails.value[r.cirId]=signature({details:payload});success('检查结果已保存')}catch(e){fail(e)}}
function clearDraft(){draft.orId=null;draft.title='';draft.content=''} function editConclusion(i){draft.orId=i.orId;draft.title=i.title;draft.content=i.content||''}
async function saveConclusion(){try{const payload={orderId:selected.value.orderId,title:draft.title,content:draft.content};if(draft.orId)payload.orId=draft.orId;await call(draft.orId?'/overallResult/updateOverallResult':'/overallResult/saveOverallResult',payload);clearDraft();conclusions.value=await call('/overallResult/listOverallResultByOrderId',{orderId:selected.value.orderId});success('总检结论已保存')}catch(e){fail(e)}}
async function removeConclusion(i){try{await ElMessageBox.confirm('确定删除这条结论吗？','删除结论',{confirmButtonText:'删除',cancelButtonText:'取消',type:'warning'})}catch{return}try{await call('/overallResult/removeOverallResult',{orderId:selected.value.orderId,orId:i.orId});conclusions.value=await call('/overallResult/listOverallResultByOrderId',{orderId:selected.value.orderId});success('结论已删除')}catch(e){fail(e)}}
async function archiveOrder(){try{await ElMessageBox.confirm('确认归档该预约？归档后页面将不再允许编辑。','归档报告',{confirmButtonText:'确认归档',cancelButtonText:'取消',type:'warning'})}catch{return}try{const n=await call('/orders/updateOrdersState',{orderId:selected.value.orderId,state:2});if(!n){error.value='该预约不存在或已归档，请刷新';return}selected.value.state=2;success('预约已归档')}catch(e){if(e.response?.status===409)error.value='请先填写并保存全部检查结果，至少添加一条总检结论。';else fail(e)}}
onMounted(async()=>{try{const raw=sessionStorage.getItem('tijianDoctor');if(raw){const d=JSON.parse(raw);const session=await api.get('/auth/session');if(session.data.doctorCode!==d.docCode)throw new Error('session mismatch');const profile=await api.get('/doctor/me');if(!profile.data || profile.data.docCode!==d.docCode)throw new Error('profile mismatch');doctor.value=profile.data;sessionStorage.setItem('tijianDoctor',JSON.stringify(profile.data));await init();initialized.value=true;if(route.name==='login')await router.replace('/ordersList');else await syncRoute()}}catch(e){sessionStorage.removeItem('tijianDoctor');doctor.value=null;initialized.value=false;await router.replace('/login')}})
</script>
<style>
*{box-sizing:border-box}body{margin:0;font-family:Inter,"Microsoft YaHei",sans-serif;color:#1a3246;background:#f3f7f8}button,input,select,textarea{font:inherit}button{cursor:pointer}button:disabled{opacity:.48;cursor:not-allowed}h1,h2,h3,p{margin:0}.login-shell{min-height:100vh;display:grid;place-items:center;background:radial-gradient(circle at 15% 15%,#d7f0e9,transparent 38%),linear-gradient(130deg,#eef8f5,#eaf0f6)}.login-card{width:min(430px,calc(100% - 32px));background:white;padding:44px;border:1px solid #e1ece9;box-shadow:0 22px 65px #244c4320;border-radius:18px}.brand-mark,.side-icon{background:#0c8770;color:white;border-radius:12px;display:grid;place-items:center}.brand-mark{width:48px;height:48px;font-size:25px;margin-bottom:30px}.eyebrow{color:#11927a;font-size:11px;letter-spacing:.15em;font-weight:800;margin-bottom:10px}.login-card h1{font-size:29px}.sub{color:#8495a2;font-size:14px;line-height:1.65;margin-top:8px}.login-form,.conclusion-form{display:grid;gap:18px;margin-top:27px}label{font-size:13px;font-weight:600;color:#3f5665;display:grid;gap:8px}input,select,textarea{width:100%;border:1px solid #dbe5e9;border-radius:8px;padding:11px 12px;color:#243d50;background:#fff;outline:none}input:focus,select:focus,textarea:focus{border-color:#18a88a;box-shadow:0 0 0 3px #d8f2eb}textarea{resize:vertical}.primary,.secondary{border-radius:8px;padding:10px 17px;font-weight:650;border:1px solid transparent}.primary{background:#0d8d73;color:#fff}.primary:hover{background:#09725d}.secondary{background:white;border-color:#dbe6e8;color:#365769}.hint{margin-top:28px;font-size:12px;color:#a2b1ba;text-align:center}.error{color:#b14b42;background:#fff2f0;padding:12px;border-radius:8px;margin-top:15px;font-size:13px}.app-shell{display:flex;min-height:100vh}.sidebar{width:225px;background:#123b3c;color:#e1efec;padding:28px 16px;display:flex;flex-direction:column;position:sticky;top:0;height:100vh;flex-shrink:0}.side-brand{display:flex;align-items:center;gap:11px;padding:0 8px}.side-icon{width:40px;height:40px;background:#1a9d84;font-size:20px}.side-brand strong,.side-bottom strong{display:block;font-size:15px}.side-brand small,.side-bottom small{display:block;color:#a6c6c0;font-size:11px;margin-top:4px}.nav-label{font-size:11px;color:#8ab1a9;margin:55px 10px 12px}.nav-item{background:none;border:0;text-align:left;color:#d7efea;padding:13px;border-radius:8px}.nav-item span{margin-left:8px}.nav-item.active{background:#246157}.side-bottom{margin-top:auto;display:flex;align-items:center;gap:9px;border-top:1px solid #356363;padding-top:20px}.avatar{background:#3b7669;border-radius:50%;width:34px;height:34px;display:grid;place-items:center}.logout{margin-left:auto;color:#c1d8d3;background:none;border:0;font-size:12px}.workspace{min-width:0;flex:1}.topbar{height:68px;background:#fff;border-bottom:1px solid #e6eeee;display:flex;align-items:center;justify-content:space-between;padding:0 38px;font-size:13px}.crumb,.slash{color:#9aabb4}.slash{margin:0 8px}.top-tag{font-size:11px;background:#e9f7f2;color:#16876d;border-radius:20px;padding:7px 11px}.content{max-width:1450px;margin:auto;padding:35px 40px}.page-head{display:flex;align-items:center;justify-content:space-between;gap:20px;margin-bottom:25px}.page-head h2{font-size:27px;letter-spacing:-.02em}.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-bottom:22px}.metric{background:#fff;border:1px solid #e2ecec;border-radius:12px;padding:19px 21px;display:grid;gap:8px}.metric span,.metric small{font-size:12px;color:#92a3ac}.metric strong{font-size:25px;color:#174d48}.metric.note strong{font-size:17px}.panel{background:white;border:1px solid #e3ebec;border-radius:12px;box-shadow:0 5px 18px #365f5a09}.panel-title{display:flex;justify-content:space-between;align-items:center;gap:15px;padding:22px 24px}.panel-title h3{font-size:16px}.panel-title p{font-size:12px;color:#9aaab2;margin-top:6px}.filters{padding:0 24px 21px;display:flex;flex-wrap:wrap;gap:10px}.filters input{max-widt